(()=>{'use strict';const active=new Set();function clear(r){delete r.panel.dataset.skeletonGeometry;const s=r.layoutSkeleton;if(!s)return;r.panel.style.cssText=s.panelStyle;r.region.style.cssText=s.regionStyle;r.region.hidden=s.hidden;r.region.inert=s.inert;if(s.aria===null)r.region.removeAttribute('aria-hidden');else r.region.setAttribute('aria-hidden',s.aria);r.skeleton.replaceChildren(...s.children);r.panel.classList.remove('bloom-geometry-overlay');delete r.layoutSkeleton;active.delete(r)}function update(r){const s=r.layoutSkeleton;if(!s)return;if(!r.region.isConnected){clear(r);return;}const rect=r.region.getBoundingClientRect(),parent=r.panel.offsetParent,pr=parent?.getBoundingClientRect()||{left:0,top:0};r.panel.style.left=(rect.left-pr.left+(parent?.scrollLeft||0)-(parent?.clientLeft||0))+'px';r.panel.style.top=(rect.top-pr.top+(parent?.scrollTop||0)-(parent?.clientTop||0))+'px';r.panel.style.width=rect.width+'px';r.panel.style.height=rect.height+'px';const bounds=s.nodes.filter(e=>e.isConnected).map(e=>e.getBoundingClientRect()).filter(b=>b.width>4&&b.height>4);r.skeleton.replaceChildren();for(const b of bounds.length?bounds:[rect]){const left=Math.max(0,b.left-rect.left),top=Math.max(0,b.top-rect.top),width=Math.min(rect.width-left,b.width),height=Math.min(rect.height-top,b.height);if(width<=0||height<=0)continue;const box=document.createElement('span');box.style.left=left+'px';box.style.top=top+'px';box.style.width=width+'px';box.style.height=height+'px';r.skeleton.append(box)}}function after(r,state,retain){if(state!=='loading'||retain||!r.region||!r.region.isConnected)return;const hidden=r.originalHidden;r.region.hidden=hidden;if(hidden)return;const rect=r.region.getBoundingClientRect();if(rect.width<4||rect.height<4){r.region.hidden=true;r.panel.dataset.skeletonGeometry='unavailable-empty-layout';return}r.layoutSkeleton={panelStyle:r.panel.style.cssText,regionStyle:r.region.style.cssText,hidden,inert:r.region.inert,aria:r.region.getAttribute('aria-hidden'),children:[...r.skeleton.childNodes],nodes:[...r.region.children].slice(0,40)};active.add(r);r.region.style.visibility='hidden';r.region.inert=true;r.region.setAttribute('aria-hidden','true');r.panel.classList.add('bloom-geometry-overlay');r.panel.dataset.skeletonGeometry='measured';r.panel.style.position='absolute';r.panel.style.margin='0';r.panel.style.padding='0';r.panel.style.border='0';r.skeleton.replaceChildren();r.skeleton.hidden=false;update(r)}let queued=false;function schedule(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;for(const r of active)update(r)})}window.addEventListener('resize',schedule,{passive:true});window.addEventListener('scroll',schedule,{passive:true,capture:true});window.BloomLayoutSkeleton=Object.freeze({before:clear,after});})();